CREATE DEFINER=`root`@`localhost` PROCEDURE `get_mustard_oil_daily_stock_report` (IN `_fromdate` DATE, IN `_todate` DATE)  BEGIN
	drop table if exists daterange;
  
  CREATE TEMPORARY TABLE daterange (dte DATE); 

SET @counter := -1;
WHILE (@counter < DATEDIFF(DATE(_todate), DATE(_fromdate))) DO 
    INSERT daterange VALUES (DATE_ADD(_fromdate, INTERVAL @counter:=@counter + 1 DAY));
END WHILE;
select dte as report_date
      ,get_opening_stock_mustard_oil(3,dte) as opening_balance
       -- ,product_manufactured_outward(3,dte) as moil_used
       ,product_manufactured_inward(3,dte) as moil_manufactured_inward
       ,quantity_of_product_sold(3,dte) as product_sold
       ,(select group_concat(memo_number)
  from sale_details
inner join sale_master on sale_details.sale_master_id=sale_master.sale_master_id
where sale_details.product_id=3 and sale_master.sale_date=dte) as memo_numbers
      -- ,mustard_seed_manufacturing_wastage(dte) as wastage

from daterange;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `get_mustard_seed_daily_stock_report` (IN `_fromdate` DATE, IN `_todate` DATE)  BEGIN
	drop table if exists daterange;
  
  CREATE TEMPORARY TABLE daterange (dte DATE); 

SET @counter := -1;
WHILE (@counter < DATEDIFF(DATE(_todate), DATE(_fromdate))) DO 
    INSERT daterange VALUES (DATE_ADD(_fromdate, INTERVAL @counter:=@counter + 1 DAY));
END WHILE;
select dte as report_date
      ,(select group_concat(person.person_name) from purchase_details
        inner join purchase_master on purchase_details.purchase_master_id = purchase_master.purchase_master_id
        inner join person on purchase_master.employee_id = person.person_id
        where purchase_master.purchase_date=dte and purchase_details.product_id=1 
        group by purchase_master.purchase_date) as vendor_names

      ,get_opening_stock_mustard_seed(1,dte) as opening_balance
      ,product_purchased_by_date(1,dte) as mustard_seed_purchased
      ,product_manufactured_outward(1,dte) as mustard_seed_used
      ,product_manufactured_inward(3,dte) as produced_moil
      ,product_manufactured_inward(2,dte) as produced_oil_cake
      -- ,product_manufactured_inward(1,dte) as product_manufactured_inward
      -- ,quantity_of_product_sold(1,dte) as product_sold
      ,mustard_seed_manufacturing_wastage(dte) as wastage

from daterange;
END$$

