CREATE DEFINER=`root`@`localhost` PROCEDURE `get_stock_report_by_date` (IN `temp_product_id` INT(11), IN `temp_date` DATE)  NO SQL
BEGIN

select get_opening_stock(temp_product_id, temp_date) as opening_stock,
product_purchased_by_date(temp_product_id, temp_date) as product_purchased,
product_manufactured_inward(temp_product_id, temp_date) as manufactured_inward,
product_manufactured_outward(temp_product_id, temp_date) as manufactured_outward,
quantity_of_product_sold(temp_product_id,temp_date) as product_sold,
mustard_seed_manufacturing_wastage(temp_date) as product_wastage;

END$$

