CREATE DEFINER=`root`@`localhost` FUNCTION `get_moil_production` (`opening_date` DATE) RETURNS DOUBLE BEGIN
	DECLARE moil DOUBLE;
  select sum(inward) into moil
from stock_production_details where stock_production_master_id in 
(select stock_production_master_id from stock_transaction where product_id=1 and date(transaction_date)=opening_date and outward>0)
and product_id=3 group by product_id;

IF moil is not null then
    RETURN moil;
 else
    RETURN 0;
  end if;
	
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `get_oil_cake_production` (`opening_date` DATE) RETURNS DOUBLE BEGIN
	DECLARE cake DOUBLE;
  
  select sum(inward) into cake
from stock_production_details where stock_production_master_id in 
(select stock_production_master_id from stock_transaction where product_id=1 and date(transaction_date)=opening_date and outward>0)
and product_id=2 group by product_id;
  IF cake is not null then
    RETURN cake;
   else
    RETURN 0;
  end if;


END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `get_opening_stock` (`temp_product_id` INT(11), `temp_opening_date` DATE) RETURNS DOUBLE NO SQL
BEGIN
	  DECLARE op_balance DOUBLE;
    DECLARE item_produced DOUBLE;
    DECLARE item_used DOUBLE;
    DECLARE item_purchased DOUBLE;
    DECLARE item_sold DOUBLE;
    DECLARE final_opeing_balance DOUBLE;
    
    /*get opening balance from product table*/
  	SELECT opening_balance into op_balance FROM `product` where product_id = temp_product_id  
    and opening_date <= temp_opening_date;

    IF op_balance is null then
      SET op_balance = 0;
    END IF;
  
  /*get inward and outward of product from production table*/
  select sum(IFNULL(inward,0)),sum(IFNULL(outward,0))into item_produced,item_used from stock_production_details
inner join stock_production_master on stock_production_details.stock_production_master_id=stock_production_master.stock_production_master_id
where stock_production_details.product_id= temp_product_id and production_date < temp_opening_date;

IF item_produced is null then
    SET item_produced = 0;
END IF;

IF item_used is null then
    SET item_used = 0;
END IF;



/*get quantity of product from purchase table*/
select sum(quantity) into item_purchased from purchase_details
inner join purchase_master on purchase_details.purchase_master_id=purchase_master.purchase_master_id
where product_id=temp_product_id and purchase_date < temp_opening_date;

  IF item_purchased is null then
    SET item_purchased = 0;
  END IF;
  
   /*get quantity of product from sale table*/
select sum(quantity) into item_sold from sale_details
inner join sale_master on sale_details.sale_master_id=sale_master.sale_master_id
where sale_details.product_id=temp_product_id and sale_master.sale_date < temp_opening_date;

  IF item_sold is null then
    SET item_sold = 0;
  END IF;

SET final_opeing_balance= (op_balance + item_produced - item_used + item_purchased - item_sold);

RETURN ROUND(final_opeing_balance,2);
  
END$$

