CREATE DEFINER=`root`@`localhost` FUNCTION `mustard_seed_manufacturing_wastage` (`temp_date` DATE) RETURNS DOUBLE BEGIN
  declare manufactured_outward DOUBLE;
  declare manufactured_inward DOUBLE;
  declare wastage DOUBLE;
    
select sum(IFNULL(inward,0)),sum(IFNULL(outward,0)) into manufactured_inward,manufactured_outward
from stock_production_details
inner join stock_production_master ON stock_production_master.stock_production_master_id = stock_production_details.stock_production_master_id
where stock_production_details.stock_production_master_id IN 
(select stock_production_master_id from stock_production_details where product_id = 1)
and stock_production_master.production_date=temp_date;

IF manufactured_inward is null then
    SET manufactured_inward=0;
end if;

IF manufactured_outward is null then
    SET manufactured_outward=0;
end if;
SET wastage = ROUND((manufactured_outward - manufactured_inward),2);
return wastage;

END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `no_of_oil_tin_for_sale` (`oil_tin_id` INT(11)) RETURNS INT(11) BEGIN
	DECLARE oil_tin_in DOUBLE;
    DECLARE oil_tin_out DOUBLE;
    DECLARE oil_tin_for_sale DOUBLE;
    DECLARE opening_stock DOUBLE;
    
    select opening_balance into opening_stock from product where product_id=oil_tin_id;
     IF opening_stock IS NULL THEN
      SET opening_stock=0;
     END IF;
    select sum(IFNULL(inward,0)) into oil_tin_in from stock_production_details where product_id=oil_tin_id;
    IF oil_tin_in IS NULL THEN
      SET oil_tin_in=0;
    END IF;
    
    select sum(IFNULL(quantity,0)) into oil_tin_out from sale_details where product_id=oil_tin_id;
    
    IF oil_tin_out IS NULL THEN
      SET oil_tin_out=0;
    END IF;
    
    SET oil_tin_for_sale= (opening_stock + oil_tin_in - oil_tin_out);
    return oil_tin_for_sale;
   

END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `product_manufactured_inward` (`temp_product_id` INT(11), `temp_date` DATE) RETURNS DOUBLE NO SQL
BEGIN
	declare product_inward_amount DOUBLE;
    
    select sum(inward) INTO product_inward_amount from stock_production_details
inner join stock_production_master ON stock_production_master.stock_production_master_id = stock_production_details.stock_production_master_id
where stock_production_master.production_date = temp_date and stock_production_details.product_id=temp_product_id;

IF product_inward_amount is null then
    SET product_inward_amount=0;
end if;

return product_inward_amount;

END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `product_manufactured_outward` (`temp_product_id` INT(11), `temp_date` DATE) RETURNS DOUBLE BEGIN
	declare product_outward_amount DOUBLE;
    
    select sum(outward) INTO product_outward_amount from stock_production_details
inner join stock_production_master ON stock_production_master.stock_production_master_id = stock_production_details.stock_production_master_id
where stock_production_master.production_date = temp_date and stock_production_details.product_id=temp_product_id;

IF product_outward_amount is null then
    SET product_outward_amount=0;
end if;

return product_outward_amount;

END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `product_purchased_by_date` (`temp_product_id` INT(11), `temp_date` DATE) RETURNS DOUBLE BEGIN
	declare purchased_amount DOUBLE;
    
select sum(quantity) into purchased_amount from purchase_details
inner join purchase_master on purchase_details.purchase_master_id = purchase_master.purchase_master_id
where purchase_details.product_id=temp_product_id and purchase_master.purchase_date=temp_date;

IF purchased_amount is null then
    SET purchased_amount=0;
end if;

return purchased_amount;

END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `quantity_of_product_sold` (`temp_product_id` INT(11), `temp_date` DATE) RETURNS DOUBLE NO SQL
BEGIN
	DECLARE item_sold DOUBLE;
  
  select sum(quantity) into item_sold
  from sale_details
inner join sale_master on sale_details.sale_master_id=sale_master.sale_master_id
where sale_details.product_id=temp_product_id and sale_master.sale_date=temp_date;


  IF item_sold is null then
    SET item_sold = 0;
  END IF;

return item_sold;



END$$

